import { PRESELECT_SKIP_DEFAULT, type PreselectionConfigEntry, type PreselectPageValue } from './preselectionConfig';
import { isObject, isString, parseKitSettingJson } from '../utils';
import { isPageValuePath } from './pageValue';
import { isPaymentFamily } from '../paymentFamily';
import { isSelectPlacementsAttributePersistenceDenied } from '../selectPlacementsAttributePersistence';

const SUPPORTED_SCHEMA_VERSION = 1;

// Matches the limit enforced when the setting is saved, and keeps the hold well under the 2^31-1 ms timer cap.
const MAX_DISPATCH_DELAY_MS = 60000;

export type PreselectionConfigSettingResult = { entries: PreselectionConfigEntry[] } | { error: string };

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every(isString);
}

function isNonEmptyString(value: unknown): value is string {
  return isString(value) && value !== '';
}

const CLIENT_TYPES = ['DesktopWeb', 'MobileWeb'];

// Matches the launcher, which reads at most this many values for a key.
const MAX_MATCH_GROUP_VALUES = 50;

// Two or more values to a group, each value in one group only and never one the default skips, at most 50 in all.
function isMatchGroups(matchGroups: unknown, skipValues: unknown): boolean {
  if (!Array.isArray(matchGroups) || matchGroups.length === 0) {
    return false;
  }
  if (!matchGroups.every((group) => isStringArray(group) && group.length >= 2 && group.every(isNonEmptyString))) {
    return false;
  }
  const values = (matchGroups as string[][]).flat();
  if (values.length > MAX_MATCH_GROUP_VALUES || new Set(values).size !== values.length) {
    return false;
  }
  const skipped = isStringArray(skipValues) ? skipValues.map((skipValue) => skipValue.toLowerCase()) : [];
  return !values.some((value) => skipped.includes(value.toLowerCase()));
}

// Matches the limits enforced when the setting is saved. A selector the browser can't parse is skipped when a click
// is matched, so only the shape is checked here.
const MAX_INTENT_SELECTORS = 10;
const MAX_INTENT_SELECTOR_LENGTH = 256;
const INTENT_SELECTOR_KINDS = ['commit', 'checkoutStep'];

// An object holding commit or checkoutStep, each a list of 1-10 non-empty selectors of at most 256 characters. Other
// keys are ignored so a later kit can add a kind, but at least one known kind must be set.
function isIntentSelectors(value: unknown): boolean {
  if (!isObject(value)) {
    return false;
  }
  const kinds = INTENT_SELECTOR_KINDS.filter((kind) => value[kind] !== undefined);
  return (
    kinds.length > 0 &&
    kinds.every((kind) => {
      const selectors = value[kind];
      return (
        isStringArray(selectors) &&
        selectors.length > 0 &&
        selectors.length <= MAX_INTENT_SELECTORS &&
        selectors.every((selector) => selector.trim() !== '' && selector.length <= MAX_INTENT_SELECTOR_LENGTH)
      );
    })
  );
}

// Keyed in lower case and trimmed, as the page's value is read.
function isPageValueDefault(value: unknown): boolean {
  return (
    isObject(value) &&
    isPageValuePath(value.path) &&
    isObject(value.values) &&
    Object.keys(value.values).length > 0 &&
    Object.entries(value.values).every(
      ([pageValue, fill]) => pageValue !== '' && pageValue === pageValue.trim().toLowerCase() && isNonEmptyString(fill),
    )
  );
}

// Fields this kit does not know are ignored, as they are on the entry, so a later kit can add one.
function isAttributeDefault(value: unknown): boolean {
  if (isNonEmptyString(value)) {
    return true;
  }
  if (!isObject(value)) {
    return false;
  }

  const { byClientType, byHostname, byPaymentPick, skipRemembered, skipValues, matchGroups, matchPaymentFamily } = value;
  const { byPageValue } = value;
  if (value.value !== undefined && !isNonEmptyString(value.value)) {
    return false;
  }
  if (byPageValue !== undefined && !isPageValueDefault(byPageValue)) {
    return false;
  }
  if (
    byClientType !== undefined &&
    (!isObject(byClientType) ||
      !Object.entries(byClientType).every(
        ([type, typeValue]) => CLIENT_TYPES.includes(type) && isNonEmptyString(typeValue),
      ))
  ) {
    return false;
  }
  // A page's host always reads in lower case, so any other key could never match.
  if (
    byHostname !== undefined &&
    (!isObject(byHostname) ||
      !Object.entries(byHostname).every(
        ([host, hostValue]) => host !== '' && host === host.toLowerCase() && isNonEmptyString(hostValue),
      ))
  ) {
    return false;
  }
  // Keyed by the kit's payment family names only, since a pick is only ever stored as one of them.
  if (
    byPaymentPick !== undefined &&
    (!isObject(byPaymentPick) ||
      Object.keys(byPaymentPick).length === 0 ||
      !Object.entries(byPaymentPick).every(
        ([family, familyValue]) => isPaymentFamily(family) && isNonEmptyString(familyValue),
      ))
  ) {
    return false;
  }
  if (skipRemembered !== undefined && typeof skipRemembered !== 'boolean') {
    return false;
  }
  if (matchPaymentFamily !== undefined && typeof matchPaymentFamily !== 'boolean') {
    return false;
  }
  if (
    skipValues !== undefined &&
    (!isStringArray(skipValues) || skipValues.length === 0 || !skipValues.every(isNonEmptyString))
  ) {
    return false;
  }
  // A value the default fills can't also be one it skips, or a shopper with none would be called on a value that
  // stops the call for a shopper who holds it.
  if (isStringArray(skipValues)) {
    const skipped = skipValues.map((skipValue) => skipValue.toLowerCase());
    // Only a device's "skip" is the no-fill sentinel; as a plain or host value it is filled like any other.
    const filled = [
      value.value,
      ...Object.values(byClientType ?? {}).filter((fill) => fill !== PRESELECT_SKIP_DEFAULT),
      ...Object.values(byHostname ?? {}),
      ...Object.values(byPaymentPick ?? {}),
      ...Object.values((byPageValue as PreselectPageValue | undefined)?.values ?? {}),
    ];
    if (filled.some((fill) => isString(fill) && skipped.includes(fill.toLowerCase()))) {
      return false;
    }
  }
  if (matchGroups !== undefined && !isMatchGroups(matchGroups, skipValues)) {
    return false;
  }
  // byPageValue never counts: kits that predate it ignore it, and a default with nothing else would fail them.
  return (
    value.value !== undefined || byClientType !== undefined || byHostname !== undefined || byPaymentPick !== undefined
  );
}

// An identifier goes out as written, so it must be non-empty with no whitespace or control characters.
export function isIdentifier(value: unknown): value is string {
  return (
    isNonEmptyString(value) &&
    !/\s/.test(value) &&
    !Array.from(value).some(
      (char) => char.charCodeAt(0) < 0x20 || (char.charCodeAt(0) >= 0x7f && char.charCodeAt(0) <= 0x9f),
    )
  );
}

function isIdentifierMap(map: unknown, isKey: (key: string) => boolean): boolean {
  return (
    isObject(map) &&
    Object.keys(map).length > 0 &&
    Object.entries(map).every(([key, identifier]) => isKey(key) && isIdentifier(identifier))
  );
}

// At least one of the three maps, each keyed as a default's are. Other keys are ignored so a later kit can add one.
function isAlternateTargetPageIdentifiers(value: unknown): boolean {
  if (!isObject(value)) {
    return false;
  }
  const { byPaymentPick, byHostname, byClientType } = value;
  const maps: Array<[unknown, (key: string) => boolean]> = [
    [byPaymentPick, isPaymentFamily],
    [byHostname, (host) => host !== '' && host === host.toLowerCase()],
    [byClientType, (type) => CLIENT_TYPES.includes(type)],
  ];
  const present = maps.filter(([map]) => map !== undefined);
  return present.length > 0 && present.every(([map, isKey]) => isIdentifierMap(map, isKey));
}

// Every identifier a target page's call can match this entry under.
export function getEntryTargetPageIdentifiers(entry: PreselectionConfigEntry): string[] {
  const alternates = entry.alternateTargetPageIdentifiers;
  return [
    entry.targetPageIdentifier,
    ...Object.values(alternates?.byPaymentPick ?? {}),
    ...Object.values(alternates?.byHostname ?? {}),
    ...Object.values(alternates?.byClientType ?? {}),
  ];
}

// Reasons name the field only, never its value, since they ship over the logging pipeline.
function parseEntry(accountId: string, raw: unknown): PreselectionConfigEntry | string {
  if (!isObject(raw)) {
    return 'not an object';
  }

  const { pathname, pathnames, targetPageIdentifier, attributeKeys, optionalAttributeKeys, identityKeys, dispatchDelayMs } = raw;
  const { triggerEventNames, releaseHoldOnRouteChange, readEmailInput, cartIntent, cartUserAttribute } = raw;
  const { checkoutStepIntent, intentSelectors, hosts } = raw;
  // The older name for the same field, read until every setting has moved to the new one.
  const legacyDefaults = raw.preselectAttributeOverrides;
  const defaults = raw.preselectAttributeDefaults !== undefined ? raw.preselectAttributeDefaults : legacyDefaults;
  const widenedOptionalKeys = raw.widenedOptionalAttributeKeys;
  const { targetPageIdentifierAttribute } = raw;
  const alternateTargets = raw.alternateTargetPageIdentifiers;

  if (raw.accountId !== undefined && raw.accountId !== accountId) {
    return 'accountId';
  }
  if (!isString(pathname) || !pathname.startsWith('/')) {
    return 'pathname';
  }
  if (
    pathnames !== undefined &&
    (!isStringArray(pathnames) ||
      pathnames.length === 0 ||
      !pathnames.every((entryPathname) => entryPathname.startsWith('/')))
  ) {
    return 'pathnames';
  }
  if (!isString(targetPageIdentifier) || targetPageIdentifier === '') {
    return 'targetPageIdentifier';
  }
  // Rejected rather than dropped: without it the entry would fire under targetPageIdentifier, a target it never meets.
  // A key the kit never persists (country, language, currency and the rest of the persistence deny list) is rejected
  // too: a fire recovered after a navigation reads its saved snapshot, which holds no such key, and a target page's
  // call reads the saved attributes, which hold none either, so the entry's early call could never be matched.
  if (
    targetPageIdentifierAttribute !== undefined &&
    (!isString(targetPageIdentifierAttribute) ||
      targetPageIdentifierAttribute.trim() === '' ||
      isSelectPlacementsAttributePersistenceDenied(targetPageIdentifierAttribute.trim()))
  ) {
    return 'targetPageIdentifierAttribute';
  }
  // Both choose the call's identifier, so an entry names one at most.
  if (
    alternateTargets !== undefined &&
    (targetPageIdentifierAttribute !== undefined || !isAlternateTargetPageIdentifiers(alternateTargets))
  ) {
    return 'alternateTargetPageIdentifiers';
  }
  if (!isStringArray(attributeKeys) || attributeKeys.length === 0) {
    return 'attributeKeys';
  }
  if (
    optionalAttributeKeys !== undefined &&
    (!isStringArray(optionalAttributeKeys) || !optionalAttributeKeys.every((key) => attributeKeys.includes(key)))
  ) {
    return 'optionalAttributeKeys';
  }
  if (
    widenedOptionalKeys !== undefined &&
    (!isStringArray(widenedOptionalKeys) || !widenedOptionalKeys.every((key) => attributeKeys.includes(key)))
  ) {
    return 'widenedOptionalAttributeKeys';
  }
  if (
    identityKeys !== undefined &&
    (!isStringArray(identityKeys) ||
      identityKeys.length === 0 ||
      !identityKeys.every((key) => attributeKeys.includes(key)))
  ) {
    return 'identityKeys';
  }
  // A widened tab can fire without its optional and widened keys, in any casing. The launcher accepts a key that
  // call left out only when it carried every identity key, so the entry needs identityKeys outside both lists.
  if (isStringArray(widenedOptionalKeys) && widenedOptionalKeys.length > 0) {
    const relaxedKeys = (isStringArray(optionalAttributeKeys) ? optionalAttributeKeys : [])
      .concat(widenedOptionalKeys)
      .map((key) => key.toLowerCase());
    if (!isStringArray(identityKeys) || identityKeys.some((key) => relaxedKeys.includes(key.toLowerCase()))) {
      return 'identityKeys';
    }
  }
  if (
    dispatchDelayMs !== undefined &&
    (!Number.isInteger(dispatchDelayMs) ||
      (dispatchDelayMs as number) < 0 ||
      (dispatchDelayMs as number) > MAX_DISPATCH_DELAY_MS)
  ) {
    return 'dispatchDelayMs';
  }
  if (releaseHoldOnRouteChange !== undefined && typeof releaseHoldOnRouteChange !== 'boolean') {
    return 'releaseHoldOnRouteChange';
  }
  if (checkoutStepIntent !== undefined && typeof checkoutStepIntent !== 'boolean') {
    return 'checkoutStepIntent';
  }
  if (cartIntent !== undefined && typeof cartIntent !== 'boolean') {
    return 'cartIntent';
  }
  if (intentSelectors !== undefined && !isIntentSelectors(intentSelectors)) {
    return 'intentSelectors';
  }
  // A page's host always reads in lower case, so any other value could never match.
  if (
    hosts !== undefined &&
    (!isStringArray(hosts) || hosts.length === 0 || !hosts.every((h) => h !== '' && h === h.toLowerCase()))
  ) {
    return 'hosts';
  }
  if (
    readEmailInput !== undefined &&
    (typeof readEmailInput !== 'boolean' ||
      !attributeKeys.includes('email') ||
      (isStringArray(optionalAttributeKeys) && optionalAttributeKeys.includes('email')) ||
      // The runtime matches optional keys in any casing, so an 'Email' key would make email optional too.
      (isStringArray(widenedOptionalKeys) && widenedOptionalKeys.some((key) => key.toLowerCase() === 'email')) ||
      // A default makes its key optional too, and would send a guessed email as the shopper's.
      (isObject(defaults) && Object.keys(defaults).some((key) => key.toLowerCase() === 'email')))
  ) {
    return 'readEmailInput';
  }
  if (raw.preselectAttributeDefaults !== undefined && legacyDefaults !== undefined) {
    return 'preselectAttributeDefaults';
  }
  // No default on an email or identity key, in any casing, which would send a guess as the shopper's own. Under the
  // older name, a value the released kit accepted as an override is dropped instead, so a setting that worked keeps
  // its entries.
  let parsedDefaults: Record<string, unknown> | undefined;
  if (defaults !== undefined) {
    const defaultsReason =
      raw.preselectAttributeDefaults !== undefined ? 'preselectAttributeDefaults' : 'preselectAttributeOverrides';
    if (!isObject(defaults)) {
      return defaultsReason;
    }
    const identityKeysLower = (isStringArray(identityKeys) ? identityKeys : []).map((key) => key.toLowerCase());
    const isValidDefault = ([key, value]: [string, unknown]): boolean =>
      isAttributeDefault(value) &&
      attributeKeys.includes(key) &&
      !['email', 'emailsha256'].includes(key.toLowerCase()) &&
      !identityKeysLower.includes(key.toLowerCase());
    const wasAcceptedOverride = ([key, value]: [string, unknown]): boolean =>
      legacyDefaults !== undefined &&
      isString(value) &&
      attributeKeys.includes(key) &&
      !(isStringArray(identityKeys) && identityKeys.includes(key));
    const defaultEntries = Object.entries(defaults);
    if (!defaultEntries.every((defaultEntry) => isValidDefault(defaultEntry) || wasAcceptedOverride(defaultEntry))) {
      return defaultsReason;
    }
    parsedDefaults = Object.fromEntries(defaultEntries.filter(isValidDefault));
  }
  if (
    triggerEventNames !== undefined &&
    (!isStringArray(triggerEventNames) ||
      triggerEventNames.length === 0 ||
      triggerEventNames.some((name) => name === ''))
  ) {
    return 'triggerEventNames';
  }

  const entry: PreselectionConfigEntry = { accountId, pathname, targetPageIdentifier, attributeKeys };
  const copyDefined = (source: Record<string, unknown>, target: object, keys: string[]): void =>
    keys.forEach((key) => {
      if (source[key] !== undefined) {
        (target as Record<string, unknown>)[key] = source[key];
      }
    });
  copyDefined(raw, entry, ['pathnames']);
  if (targetPageIdentifierAttribute !== undefined) {
    entry.targetPageIdentifierAttribute = targetPageIdentifierAttribute.trim();
  }
  if (alternateTargets !== undefined) {
    entry.alternateTargetPageIdentifiers = {};
    copyDefined(alternateTargets as Record<string, unknown>, entry.alternateTargetPageIdentifiers, [
      'byPaymentPick',
      'byHostname',
      'byClientType',
    ]);
  }
  copyDefined(raw, entry, [
    'optionalAttributeKeys',
    'widenedOptionalAttributeKeys',
    'identityKeys',
    'dispatchDelayMs',
    'releaseHoldOnRouteChange',
    'checkoutStepIntent',
    'intentSelectors',
    'hosts',
    'readEmailInput',
  ]);
  if (parsedDefaults !== undefined) {
    entry.preselectAttributeDefaults = parsedDefaults as PreselectionConfigEntry['preselectAttributeDefaults'];
  }
  copyDefined(raw, entry, ['triggerEventNames', 'cartIntent']);
  // Kept only as a non-empty string on a cartIntent entry; any other value is dropped rather than rejected.
  if (cartIntent === true && isString(cartUserAttribute) && cartUserAttribute !== '') {
    entry.cartUserAttribute = cartUserAttribute;
  }
  return entry;
}

// Any invalid entry rejects the whole setting, so a partial config can never replace a working one.
export function parsePreselectionConfigSetting(accountId: string, setting: string): PreselectionConfigSettingResult {
  const payload = parseKitSettingJson(setting);
  if (payload === undefined) {
    return { error: 'invalid JSON' };
  }

  if (!isObject(payload)) {
    return { error: 'not an object' };
  }
  if (payload.schemaVersion !== SUPPORTED_SCHEMA_VERSION) {
    return { error: 'schemaVersion' };
  }
  if (!Array.isArray(payload.entries)) {
    return { error: 'entries' };
  }

  const entries: PreselectionConfigEntry[] = [];
  for (let i = 0; i < payload.entries.length; i++) {
    const entry = parseEntry(accountId, payload.entries[i]);
    if (isString(entry)) {
      return { error: `entry ${i + 1} ${entry}` };
    }
    // A target page's call must name one entry, so no two entries share any identifier.
    const targets = getEntryTargetPageIdentifiers(entry);
    if (entries.some((existing) => getEntryTargetPageIdentifiers(existing).some((id) => targets.includes(id)))) {
      return { error: `entry ${i + 1} targetPageIdentifier` };
    }
    entries.push(entry);
  }
  return { entries };
}
