import type { PaymentFamily } from '../paymentFamily';

export type PreselectClientType = 'DesktopWeb' | 'MobileWeb';

export const PRESELECT_SKIP_DEFAULT = 'skip';

export interface PreselectPageValue {
  // Dotted segments from window, such as a data layer field.
  path: string;
  // Keyed by the page's value, trimmed and in lower case. The call sends the mapped value, never the page's own.
  values: Record<string, string>;
}

export interface PreselectAttributeDefault {
  value?: string;
  // Read when the call goes out. Beats byPaymentPick, byHostname, byClientType and value; a device's skip still wins.
  // A page value the map doesn't name, or none, falls through to the rest of the default.
  byPageValue?: PreselectPageValue;
  // PRESELECT_SKIP_DEFAULT leaves the key empty on that device, whatever value or byHostname say.
  byClientType?: Partial<Record<PreselectClientType, string>>;
  // Keyed by the exact, lowercase host of the page the call fires from.
  byHostname?: Record<string, string>;
  // Keyed by the payment family the shopper last picked on the page in this tab (a payment radio, frame or wallet
  // button), within the arrival window. Beats byHostname, byClientType and value; a device's skip still wins.
  byPaymentPick?: Partial<Record<PaymentFamily, string>>;
  // Fill even over a value saved from an earlier call, which the kit cannot tell from this page's own.
  skipRemembered?: boolean;
  // No speculative call while the shopper's own value for the key is one of these, in any casing. A fill never counts.
  skipValues?: string[];
  // Values the target page may send that count as the one this default filled: the cached offers stay when the page
  // sends any value in the filled value's group, compared exactly. A fill in no group must arrive as it went out.
  matchGroups?: string[][];
  // Match the cached offers on the payment family of the value sent, so any value of the same family keeps them.
  matchPaymentFamily?: boolean;
}

export interface PreselectAlternateTargetPageIdentifiers {
  byPaymentPick?: Partial<Record<PaymentFamily, string>>;
  byHostname?: Record<string, string>;
  byClientType?: Partial<Record<PreselectClientType, string>>;
}

export interface PreselectIntentSelectors {
  commit?: string[];
  checkoutStep?: string[];
}

// Fallback for an account whose connection has no valid preselectionConfig kit setting.
export interface PreselectionConfigEntry {
  accountId: string;
  pathname: string;
  // Additional pathnames (each starting with '/', '*' matching one segment) that also match this entry.
  pathnames?: string[];
  targetPageIdentifier: string;
  // Opt-in: the attribute key, in any casing, whose value names the target page in place of targetPageIdentifier. The
  // speculative call goes out under the trigger page's own value, read from the sources attributeKeys read, in the
  // same order, and a target page's call matches this entry when its identifier equals that call's own value. A value
  // that is missing, or that is not a non-empty string free of whitespace and control characters once trimmed, sends
  // no speculative call, and so does a value the workspace's attribute filter removes. A key on the kit's persistence
  // deny list (country, language, currency and the like) is rejected when the setting is read. targetPageIdentifier
  // still keys the entry's records, and a kit without this field uses it.
  // A target page's call whose identifier matches more than one entry, as when two entries' attributes hold the same
  // value or this value equals another entry's targetPageIdentifier, goes to none of them.
  targetPageIdentifierAttribute?: string;
  // Opt-in, for a route that ends on one of several target pages: the call goes out under the page the shopper's payment
  // pick, then the page's host, then the device names, else targetPageIdentifier, which still keys the entry's records.
  // A target page's call matches this entry under any of these identifiers.
  alternateTargetPageIdentifiers?: PreselectAlternateTargetPageIdentifiers;
  // Attributes that gate the dispatch and form the cache key. Include one only if it is
  // stable between checkout and the target page and is used to select offers; an attribute
  // that moves in between turns every arrival into a miss. Attributes on the
  // selectPlacements persistence deny list cannot survive a recovered dispatch, so they
  // miss on every recovery.
  attributeKeys: string[];
  // Keys that do not block the dispatch when unresolved. They stay in attributeKeys, so the cache
  // still matches on them and records an unresolved one as unset.
  optionalAttributeKeys?: string[];
  // Keys, listed in attributeKeys too, that are also optional on a tab the Rokt launcher marks with
  // the 'widened' pre-selection variant. Every other tab treats them as optionalAttributeKeys says.
  // A non-empty list needs identityKeys, none of them optional or widened in any casing.
  widenedOptionalAttributeKeys?: string[];
  // Keys, listed in attributeKeys too, that resolve from the user identity of the same name when no
  // attribute carries them. The launcher compares these strictly on arrival.
  identityKeys?: string[];
  // Opt-in: when no event, user attribute or identity supplies `email`, read the one the shopper typed
  // into the trigger page's form, taken only from text and email inputs the shopper typed into or
  // autofilled, and only when they hold exactly one distinct email. Only for an entry whose guests reach
  // that page without one; it needs `email` required, widened tabs included.
  readEmailInput?: boolean;
  // Milliseconds to hold the dispatch, so attributes are read after the page has settled rather
  // than at the pageview. Omit it and nothing is scheduled: the dispatch stays synchronous.
  dispatchDelayMs?: number;
  // Release a held dispatch when a later trigger moves to another route. Opt-in per entry.
  releaseHoldOnRouteChange?: boolean;
  // Opt-in: while checkout intent is active, a click on this entry's own route that the core SDK reads as a checkout
  // step, such as "Checkout" or "Proceed to checkout", fires the entry as the confirm click would. For an entry whose
  // confirm click happens on a page the kit doesn't run on. Off the route, such a click still only gets observed.
  checkoutStepIntent?: boolean;
  // CSS selectors naming the page's own confirm and checkout-step buttons. While checkout intent is active, a click on
  // a control matching one, on any route, is read as follows. A commit match counts as a confirm before the core SDK's
  // label rules. A checkoutStep match counts as a checkout step unless its labels make it a confirm, wallet or
  // add-to-cart click, which then counts as that click; a checkout step still fires only an entry with
  // checkoutStepIntent. Each selector must match the button itself, not a container.
  intentSelectors?: PreselectIntentSelectors;
  // Values the speculative call sends only for a key it has no value for, from the trigger event, the
  // shopper's saved attributes or an identity, in any casing; the shopper's own value wins unless the default
  // skips remembered values. A defaulted key counts as resolved and is never written to the saved attributes. On a
  // widened tab only a default with matchGroups or skipValues fills. List each key in attributeKeys too, never in
  // identityKeys.
  preselectAttributeDefaults?: Record<string, string | PreselectAttributeDefault>;
  // Custom event names (mParticle logEvent) that also trigger on this route, alongside the
  // pageview and pathname triggers. A matching event dispatches without dispatchDelayMs.
  triggerEventNames?: string[];
  // Opt-in: while checkout intent is active, a click that adds to or opens the cart fires this entry from any
  // route, under the confirm click's identity and email rules. Off its own route it fires only as the account's
  // one cartIntent entry. A commit or wallet tap never fires it, on its route or off it.
  cartIntent?: boolean;
  // Opt-in for the account's one cartIntent entry: the user attribute, in any casing, that holds the shopper's cart.
  // A page view off every entry's route fires it at once while that attribute holds items. A gate only, never a key.
  cartUserAttribute?: string;
  // The hosts this entry's storefront runs on, in lower case. When set, a tap off every entry's route fires the entry
  // only on one of them, so a sibling storefront sharing the account never fires it. The entry's own route ignores it.
  hosts?: string[];
}

export const PRESELECTION_CONFIG: PreselectionConfigEntry[] = [];
